/*
 * A040518  Continued fraction for sqrt(542).
 * https://oeis.org/A040518
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, cofr, easy, less
 * Formula:   a(n) is the n-th partial quotient in the continued fraction
 *            expansion of sqrt(542). The expansion is generated by the
 *            standard recurrence: m0 = 0, d0 = 1, a0 = floor(sqrt(542)) = 23
 *            m_{k+1} = d_k * a_k - m_k d_{k+1} = (542 - m_{k+1}^2) / d_k
 *            a_{k+1} = (a0 + m_{k+1}) / d_{k+1}
 * Range:     u8 n <= 87, u16 n <= 87, u32 n <= 87, u64 n <= 87, u128 n <= 87,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>
#include <stdint.h>
#include <stdbool.h>

#define D 542ULL
#define A0 23ULL

static seq_t *cache_a   = NULL;
static size_t cache_len = 0;
static size_t cache_cap = 0;
static uint64_t *cache_m = NULL;
static uint64_t *cache_d = NULL;

/* Resize the cached arrays to at least 'need' capacity */
static void ensure_capacity(size_t need)
{
    if (need <= cache_cap)
        return;
    size_t new_cap = cache_cap ? cache_cap * 2 : 16;
    if (new_cap < need)
        new_cap = need * 2;
    cache_a = (seq_t *)realloc(cache_a, new_cap * sizeof(seq_t));
    cache_m = (uint64_t *)realloc(cache_m, new_cap * sizeof(uint64_t));
    cache_d = (uint64_t *)realloc(cache_d, new_cap * sizeof(uint64_t));
    cache_cap = new_cap;
}

seq_t a(idx_t n)
{
    size_t idx = (size_t)n;          /* idx_t is unsigned 64, so cast is safe for small n */
    ensure_capacity(idx + 1);
    if (cache_len == 0) {            /* initialize the first term */
        cache_a[0] = (seq_t)A0;
        cache_m[0] = 0ULL;
        cache_d[0] = 1ULL;
        cache_len = 1;
    }
    while (cache_len <= idx) {       /* compute up to required index */
        uint64_t m_prev = cache_m[cache_len - 1];
        uint64_t d_prev = cache_d[cache_len - 1];
        seq_t a_prev = cache_a[cache_len - 1];

        uint64_t m_next = d_prev * (uint64_t)a_prev - m_prev;
        uint64_t d_next = (D - m_next * m_next) / d_prev;
        uint64_t a_next = (A0 + m_next) / d_next;

        cache_m[cache_len] = m_next;
        cache_d[cache_len] = d_next;
        cache_a[cache_len] = (seq_t)a_next;
        cache_len++;
    }
    return cache_a[idx];
}
